second_settings_local:
{
  "attribution": {
    "commit": "",
    "pr": ""
  },
  "hooks": {
    "PreToolUse": [
      {
        "matcher": "Bash",
        "hooks": [
          {
            "type": "command",
            "command": "f=\"$(git -C \"${CLAUDE_PROJECT_DIR:-.}\" rev-parse --show-toplevel 2>/dev/null)/.claude/hooks/guard-commands.py\"; if [ -f \"$f\" ]; then python3 \"$f\" --mode off --attribution on; fi",
            "timeout": 10
          }
        ]
      }
    ]
  }
}

